//! A bounded work queue with cancellation support.
//!
//! Producers submit work items; consumers receive them. The queue has a
//! fixed capacity, so `send` blocks (or fails fast in non-blocking mode)
//! when full. A cancellation token shared by all handles lets any task
//! shut the whole pipeline down: blocked senders/receivers wake up with
//! an error, and subsequent operations fail immediately.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};

/// Error type for queue operations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueError {
    /// The queue was cancelled (or was cancelled while we waited).
    Cancelled,
    /// The queue is full (non-blocking send only).
    Full,
    /// The queue is empty (non-blocking receive only).
    Empty,
}

impl fmt::Display for QueueError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueueError::Cancelled => write!(f, "queue cancelled"),
            QueueError::QueueError => unreachable!(),
        }
    }
}

impl std::error::Error for QueueError {}

